import{_ as o,o as r,c as a,a5 as d}from"./chunks/framework.Bt0SrEfo.js";const u=JSON.parse('{"title":"六、三面准备（友邦 AIA）","description":"","frontmatter":{},"headers":[],"relativePath":"副业/保险展业/06-三面准备.md","filePath":"副业/保险展业/06-三面准备.md","lastUpdated":1792683759000}'),n={name:"副业/保险展业/06-三面准备.md"};function s(e,t,l,h,g,i){return r(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="六、三面准备-友邦-aia" tabindex="-1">六、三面准备（友邦 AIA） <a class="header-anchor" href="#六、三面准备-友邦-aia" aria-label="Permalink to &quot;六、三面准备（友邦 AIA）&quot;">​</a></h1><blockquote><p>本篇是<strong>打友邦三面的作战手册</strong>。 三面由团队主管（SSC）面，评分表会逐项打&quot;差 / 一般 / 强&quot;。 这篇先摆出 7 道题，再拆评分表，最后给每道题的答法、话术和填空位。</p></blockquote><hr><h2 id="_0-七道题速览-先看题" tabindex="-1">0. 七道题速览（先看题） <a class="header-anchor" href="#_0-七道题速览-先看题" aria-label="Permalink to &quot;0. 七道题速览（先看题）&quot;">​</a></h2><p>三面就这 7 道题，顺序基本固定。<strong>先看题面，再看答法</strong>—— 下面每道题都标了&quot;主管在考什么&quot;和&quot;一句话怎么答&quot;，后面的正文是逐题展开。</p><table tabindex="0"><thead><tr><th>#</th><th>题目</th><th>主管在考什么</th><th>一句话答法</th><th>详解</th></tr></thead><tbody><tr><td>1</td><td>请用 2 分钟介绍一下自己</td><td>背景 / 经历 / 家庭情况</td><td><strong>行业下行 + AI 上行 → 想做副业 → 保险上行期</strong>，270 字成稿</td><td><a href="#q1">看详解</a></td></tr><tr><td>2</td><td>你和引荐人怎么认识的？多久了？参加过多少次活动？</td><td>真实度、投入度</td><td><strong>一年半 / 3 场 / 星享会陈静总助</strong></td><td><a href="#q2">看详解</a></td></tr><tr><td>3</td><td>介绍一下你了解的友邦，哪些吸引你，为什么想来？</td><td>是否做过功课</td><td><strong>四个年份 + 三点吸引力 + 三条标准</strong>（扎根久·客群对·能续期）</td><td><a href="#q3">看详解</a></td></tr><tr><td>4</td><td>你怎么看待保险销售？你的优势是什么？最大的挑战是什么？</td><td>观点 / 可教性 / 自我认知</td><td>3 个优势（各有证据）+ 1 个真挑战（配应对动作）</td><td><a href="#q4">看详解</a></td></tr><tr><td>5</td><td>三个月收入目标怎么设定？做好了准备吗？</td><td>目标感 + 计划性</td><td><strong>三档目标 + 逐月拆解 + 第一天做什么</strong></td><td><a href="#q5">看详解</a></td></tr><tr><td>6</td><td>了解保险工作模式吗？怎么开展业务？怎么开拓客户？</td><td>是否懂真实打法</td><td>双轮节奏 + 四条渠道 + 数量指标</td><td><a href="#q6">看详解</a></td></tr><tr><td>7</td><td>家人支持吗？孩子谁照顾？</td><td>家庭支持度（状态记录）</td><td><strong>先说支持 + 再给安排 + 最后给保障</strong></td><td><a href="#q7">看详解</a></td></tr></tbody></table><h3 id="答题通则-贯穿这-7-道题" tabindex="-1">答题通则（贯穿这 7 道题） <a class="header-anchor" href="#答题通则-贯穿这-7-道题" aria-label="Permalink to &quot;答题通则（贯穿这 7 道题）&quot;">​</a></h3><blockquote><p>🎯 一句话：<strong>每一题都要落到一个可验证的动作，而不是态度表态。</strong></p></blockquote><p>三个词，烂熟于心：<strong>数字</strong>（量化一切）· <strong>动作</strong>（下一步可验证）· <strong>安排</strong>（家庭已谈妥）</p><hr><h2 id="_1-先看懂评分表-主管在打什么分" tabindex="-1">1. 先看懂评分表：主管在打什么分 <a class="header-anchor" href="#_1-先看懂评分表-主管在打什么分" aria-label="Permalink to &quot;1. 先看懂评分表：主管在打什么分&quot;">​</a></h2><table tabindex="0"><thead><tr><th>板块</th><th>能不能改</th><th>主管真正在看什么</th></tr></thead><tbody><tr><td>概貌 · 硬件</td><td>❌ 改不了</td><td>年龄 / 学历 / 过往收入 / 人脉资源 —— 只是<strong>门槛筛</strong>，权重低，不靠这里拿分</td></tr><tr><td>概貌 · 软件</td><td>✅ 能证明</td><td>企图心、可教性、交际能力、表达能力、亲和力</td></tr><tr><td>优增过程 · 状态记录</td><td>✅ 能证明</td><td>态度：学习投入、目标感、客户开拓计划、<strong>家庭支持度</strong></td></tr></tbody></table><h3 id="三条潜台词-比题目本身更重要" tabindex="-1">三条潜台词（比题目本身更重要） <a class="header-anchor" href="#三条潜台词-比题目本身更重要" aria-label="Permalink to &quot;三条潜台词（比题目本身更重要）&quot;">​</a></h3><ol><li><p><strong>主管在算一笔账</strong>：培养一个新人 3–6 个月，我的时间成本能不能赚回来？ 所以他不是想听你说&quot;我很有热情&quot;，他想听&quot;<strong>你具体打算怎么干</strong>&quot;。</p></li><li><p><strong>&quot;差 / 一般 / 强&quot;里，&quot;一般&quot;是安全线，不是好结果。</strong> 硬件你已经定了，唯一能翻盘的板块是<strong>可教性 + 亲和力 + 状态记录</strong>。 这三项就是你的战场。</p></li><li><p><strong>最大的隐藏扣分项：没有数字。</strong> 认识引荐人多久、参加几次活动、三个月收入目标、过去收入 —— 全都要数字化。 说&quot;还在了解阶段&quot;=&quot;差&quot;；说&quot;认识 5 个月，参加过 8 场活动&quot;=&quot;强&quot;。 <strong>含糊 = 差，这是评分表里最容易被忽略的规则。</strong></p></li></ol><blockquote><p>🎯 一句话总结：<strong>每一题都要落到一个可验证的动作，而不是态度表态。</strong></p></blockquote><hr><h2 id="_2-通用原则-三面共通" tabindex="-1">2. 通用原则（三面共通） <a class="header-anchor" href="#_2-通用原则-三面共通" aria-label="Permalink to &quot;2. 通用原则（三面共通）&quot;">​</a></h2><h3 id="三条加分动作" tabindex="-1">三条加分动作 <a class="header-anchor" href="#三条加分动作" aria-label="Permalink to &quot;三条加分动作&quot;">​</a></h3><ul><li><strong>数字优先</strong>：任何能量化的都量化（时间、场次、单量、保费、好友数）</li><li><strong>主动认领挑战</strong>：说&quot;我没有挑战&quot;直接判差。认一个真挑战 + 配应对动作</li><li><strong>反问要具体</strong>：反问环节问出细节，主管会认为你做过功课</li></ul><h3 id="四个禁忌" tabindex="-1">四个禁忌 <a class="header-anchor" href="#四个禁忌" aria-label="Permalink to &quot;四个禁忌&quot;">​</a></h3><table tabindex="0"><thead><tr><th>❌ 不要</th><th>为什么</th></tr></thead><tbody><tr><td>吐槽前公司 / 前领导</td><td>主管会想&quot;你下次也这么说我&quot;</td></tr><tr><td>说&quot;先试试看&quot;&quot;干一段时间再说&quot;</td><td>直接踩&quot;投入度&quot;评分</td></tr><tr><td>说&quot;保险公司都差不多&quot;</td><td>证明你没做功课</td></tr><tr><td>只讲产品收益，不讲客户</td><td>主管不想听产品，他想听你怎么找客户</td></tr></tbody></table><h3 id="形象底线" tabindex="-1">形象底线 <a class="header-anchor" href="#形象底线" aria-label="Permalink to &quot;形象底线&quot;">​</a></h3><ul><li>准时，提前 10 分钟到；手机静音</li><li>主管说话时不要抢话，回答完停一拍，别急着补充</li><li>手机里提前查好&quot;友邦历史 / 主打产品 / 代理人制度&quot;，别现场现搜</li><li>带纸笔：记下主管名字、你主管团队多少人、他的姓名（后面跟进要用）</li></ul><hr><h3 id="q1" tabindex="-1">第 1 题：请用 2 分钟介绍一下自己 <a class="header-anchor" href="#q1" aria-label="Permalink to &quot;第 1 题：请用 2 分钟介绍一下自己 {#q1}&quot;">​</a></h3><blockquote><p>&quot;面试官好，我是 XXX，XX 岁，XX 学历，做前端开发已经 7 年。</p><p>这 7 年我感受很明显：<strong>前端在往下走</strong>，岗位在缩、要求越来越高；<strong>AI 在往上走</strong>，以前一个需求要五个人做，现在两个人加上 AI 就够了。与其继续在一条收缩的赛道上硬拼，不如去一条看得见在长的赛道上。</p><p>前几年我其实有点沉迷技术，觉得只要把技术学得够好，就能一直走下去。但这两年我也慢慢意识到，单靠一条技术线未必是全部。工资之外，我一直在想<strong>再拓展一份能长期做、还能慢慢积累的副业</strong>，而不是随便做点什么。</p><p>后来通过朋友介绍了解到友邦，也了解到<strong>保险这几年是在上行期的</strong>：老龄化在走，家庭保障意识在提高，头部公司还在扩。而代理人的时间是自己的、门槛靠积累，正好是我想要的那份副业。</p><p>这也是我来做保险的原因。&quot;</p></blockquote><hr><h3 id="q2" tabindex="-1">第 2 题：你和引荐人怎么认识的？多久了？参加过多少次活动？ <a class="header-anchor" href="#q2" aria-label="Permalink to &quot;第 2 题：你和引荐人怎么认识的？多久了？参加过多少次活动？ {#q2}&quot;">​</a></h3><blockquote><p>&quot;我是通过（<strong>引荐人姓名</strong>）认识他/她的，到现在一年半。真正开始了解友邦是最近一周多的时间，前前后后参加了 <strong>3 场活动</strong>。</p><p>印象最深的是其中一场<strong>星享会</strong>，做介绍的是<strong>陈静总助</strong>。她是总助，位置不低，但我留意到一个细节——<strong>她已经 7 年没发过朋友圈了</strong>，说明靠朋友圈能触达的人其实很有限。可她还是在拓客，切口也很朴素：<strong>发自己孩子鸡娃的视频，从生活话题切进去</strong>，再自然地聊到家庭。</p><p>那场之后我意识到一件事：<strong>做这行不是拼谁人脉多，是拼谁敢不敢从最小的话题开始</strong>。而这件事我现在就可以开始练，不需要等什么大机会。&quot;</p></blockquote><hr><h3 id="q3" tabindex="-1">第 3 题：介绍一下你了解的友邦，哪些吸引你，为什么想来？ <a class="header-anchor" href="#q3" aria-label="Permalink to &quot;第 3 题：介绍一下你了解的友邦，哪些吸引你，为什么想来？ {#q3}&quot;">​</a></h3><p><strong>四个年份 + 两句官方话：1919 · 1992 · 2010 · 2020 ·「最受信赖」· 三条标准（扎根久 / 客群对 / 能续期）</strong></p><blockquote><p>&quot;我对友邦的了解是从一条时间线开始的。</p><p><strong>1919 年</strong>，友邦在上海开启了它和中国的&#39;世纪之缘&#39;；后来因为战乱迁到了境外；<strong>1992 年</strong>重回内地；<strong>2010 年</strong>在香港上市；<strong>2020 年</strong>，友邦获准把上海分公司改建为&#39;<strong>友邦人寿保险有限公司</strong>&#39;，成为中国内地<strong>首家外资独资的人身保险公司</strong>，统一经营内地的寿险业务。</p><p>它真正吸引我的，是三点。</p><p><strong>一，角色跟我是匹配的。</strong> 它服务的是中高端客户，代理人是高学历、高素质的人才——不是到处卖保单，是顾问式的活：先专业，后产品。我做了七年技术，一直是先把事情搞懂再动手。</p><p><strong>二，它的愿景是&#39;最受信赖&#39;。</strong> 信赖不是一次成交换来的，是很多年做下来才有的东西——这正是我想做的方向。</p><p><strong>三，它 100 多年没有离开中国。</strong> 从 1919 到 2020，中间经历了战乱、开放和市场几次大变化，这种投入不是做短期能解释的。</p><p>至于为什么选择友邦，我其实只看三条标准：<strong>扎根久、客群对、能续期</strong>。扎根久就是刚才那一百多年；客群对是中高端客户加高素质代理人；能续期，是代理人的收入里有续期，保障本身有周期——我愿意做的是跟着一个家庭很多年的事，不是一锤子买卖。&quot;</p></blockquote><p><strong>这段为什么拿&quot;强&quot;</strong></p><table tabindex="0"><thead><tr><th>你说的</th><th>主管听到的</th></tr></thead><tbody><tr><td><strong>四个年份</strong></td><td>功课做足了，不是一句&quot;听说过&quot;</td></tr><tr><td><strong>&quot;最受信赖&quot;四个字</strong></td><td>抓的是价值观，不是口号</td></tr><tr><td><strong>三点吸引力</strong></td><td>你有自己的感受，不是复述宣传</td></tr><tr><td><strong>三条标准</strong></td><td>你有决策框架，不是在列优点</td></tr><tr><td><strong>能续期</strong></td><td>你在意的是长期，不是这一单</td></tr></tbody></table><p>⚠️ 三个坑：别把友邦的制度和别家混着说；别对牌照下自己没核实过的结论；别说&quot;友邦是世界五百强&quot;&quot;保险行业前景很好&quot;这类谁都能说的话。</p><hr><h4 id="代理人制度-和-进公司打工-的本质区别" tabindex="-1">代理人制度：和&quot;进公司打工&quot;的本质区别 <a class="header-anchor" href="#代理人制度-和-进公司打工-的本质区别" aria-label="Permalink to &quot;代理人制度：和&quot;进公司打工&quot;的本质区别&quot;">​</a></h4><table tabindex="0"><thead><tr><th>特点</th><th>说明</th></tr></thead><tbody><tr><td><strong>独立代理人，不是员工</strong></td><td>不签劳动合同、没有固定底薪，自负盈亏，赚的是佣金</td></tr><tr><td><strong>收入分两块</strong></td><td>首年佣金 + <strong>续期佣金</strong>；保障型产品的收入能跟着客户很多年</td></tr><tr><td><strong>两条发展线</strong></td><td>个人销售线（自己出单）+ 营销线（增员、带团队、拿双十）</td></tr><tr><td><strong>时间自由，但自我管理要求极高</strong></td><td>没人催你，也没人管你</td></tr><tr><td><strong>荣誉体系</strong></td><td>MDRT（百万美元会员）→ COT（会员大会主席）→ TOT</td></tr></tbody></table><p><strong>被问到时的说法</strong></p><blockquote><p>&quot;友邦是独立代理人制，不是我去应聘一个岗位。收入来自首年佣金和续期佣金，保障型产品的续期能跟着客户很多年。发展上有两条线：一条是自己出单，一条是增员带团队。当然，自由的另一面是没人管你——所以我需要的是自律和方法，不是打卡。&quot;</p></blockquote><p>⚠️ <strong>上场前自己核对的三点</strong>（网上说法混乱，容易说错）：具体福利/保障政策、&quot;双十&quot;的准确比例、团队晋升的基本法。被追问细节时答&quot;具体比例我回去确认给您&quot;，比说错强得多。</p><h4 id="时间紧-只给-30-秒时的压缩版" tabindex="-1">时间紧 / 只给 30 秒时的压缩版 <a class="header-anchor" href="#时间紧-只给-30-秒时的压缩版" aria-label="Permalink to &quot;时间紧 / 只给 30 秒时的压缩版&quot;">​</a></h4><blockquote><p>&quot;我选友邦只看三条标准：<strong>扎根久</strong>——1919 年就在上海，2020 年拿下首家外资独资寿险资格；<strong>客群对</strong>——做中高端客户，代理人是高素质人才，跟我的背景匹配；<strong>能续期</strong>——收入里有续期，保障有周期。我不想只卖一份保单，我想做的是能跟着客户很多年的事。&quot;</p></blockquote><blockquote><p>⚠️ 这题问的不是&quot;友邦好不好&quot;，是&quot;你有没有判断标准&quot;。所以<strong>先给标准、再用事实印证</strong> —— 没有标准，前面那几条就只是优点。</p></blockquote><hr><h3 id="q4" tabindex="-1">第 4 题：你怎么看待保险销售？你的优势是什么？最大的挑战是什么？ <a class="header-anchor" href="#q4" aria-label="Permalink to &quot;第 4 题：你怎么看待保险销售？你的优势是什么？最大的挑战是什么？ {#q4}&quot;">​</a></h3><h3 id="评分点" tabindex="-1">评分点 <a class="header-anchor" href="#评分点" aria-label="Permalink to &quot;评分点&quot;">​</a></h3><p>对保险工作的了解 + <strong>对自己的了解</strong>。这题在测&quot;清醒度&quot;。</p><h4 id="你怎么看待保险销售" tabindex="-1">你怎么看待保险销售 <a class="header-anchor" href="#你怎么看待保险销售" aria-label="Permalink to &quot;你怎么看待保险销售&quot;">​</a></h4><blockquote><p>以前我对很多保险销售的感觉是他们在卖产品。&quot;我觉得保险销售的本质不是&#39;卖产品&#39;，是<strong>帮一个家庭把它承担不了的最坏情况转移出去</strong>。</p><p>很多人买保险不是因为觉得保险公司好，是因为他们知道自己扛不住那个风险。 所以代理人真正的价值是：<strong>让客户在没出事的时候也愿意做这个决定。</strong>&quot;</p></blockquote><h4 id="优势" tabindex="-1">优势 <a class="header-anchor" href="#优势" aria-label="Permalink to &quot;优势&quot;">​</a></h4><ol><li>我学习能力、逻辑思维能力还可以，因为我做了多年技术研发工作。公司相关产品、知识能快速吸收，运用。</li><li>我自身处于it行业有一定的资源，我的未婚妻是深二代，家庭也有一定的助力。</li><li>我会经常走出去跟外人交流，溜猫、看展。</li><li>我跟多个部门同事合作，有一定的交流能力。</li></ol><h4 id="最大的挑战会是什么" tabindex="-1">最大的挑战会是什么 <a class="header-anchor" href="#最大的挑战会是什么" aria-label="Permalink to &quot;最大的挑战会是什么&quot;">​</a></h4><blockquote><p>&quot;我最大的挑战是<strong>前期的从 0 开始</strong>。</p><p>我做技术时是靠系统训练和有标准答案的考题， 但拓客没有标准答案 —— 被拒绝是常态，而且很可能连拒绝都拿不到，只是一句&#39;暂时不需要&#39;。</p><p>我对这个有两个准备： 一是<strong>降低对拒绝的敏感度</strong> —— 我准备把前三个月的每一次拒绝都当成数据记录，做复盘； 二是<strong>先跑量再跑质</strong>，比如前期每个月面谈30个客户。 从熟人到陌生：熟人市场是有限的，长期要建立陌生信任 专业知识门槛：保险、税务、法律、医学都要懂</p></blockquote><hr><h2 id="q5" tabindex="-1">7. 第 5 题：三个月收入目标怎么设定？做好了准备吗？ <a class="header-anchor" href="#q5" aria-label="Permalink to &quot;7. 第 5 题：三个月收入目标怎么设定？做好了准备吗？ {#q5}&quot;">​</a></h2><p>目前还不了解相关产品保费和佣金，无法具体测算。我的目标是先完成DA转任，1.5w佣金+6个有效单</p><h3 id="三个月拆解模板-主管最爱听这个" tabindex="-1">三个月拆解模板（主管最爱听这个） <a class="header-anchor" href="#三个月拆解模板-主管最爱听这个" aria-label="Permalink to &quot;三个月拆解模板（主管最爱听这个）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>收入目标</th><th>关键动作</th></tr></thead><tbody><tr><td><strong>第 1 月</strong></td><td>（保底级）打底</td><td>系统学完产品条款；盘点缘故市场（<strong>列出 100 个人的名单</strong>）；跟引荐人跑（<strong>10</strong>）场活动；每周新增（<strong>30</strong>）个好友</td></tr><tr><td><strong>第 2 月</strong></td><td>（目标级）</td><td>独立参加（<strong>4</strong>）场活动；完成（<strong>15</strong>）次面谈；把面谈记录整理成客户档案</td></tr><tr><td><strong>第 3 月</strong></td><td>（冲刺级）</td><td>集中促成 + 追单；启动转介绍（老客户带新客户）；第一次月度复盘复盘</td></tr></tbody></table><h3 id="🎯-杀手锏-说出-入职第一天做什么" tabindex="-1">🎯 杀手锏：说出&quot;入职第一天做什么&quot; <a class="header-anchor" href="#🎯-杀手锏-说出-入职第一天做什么" aria-label="Permalink to &quot;🎯 杀手锏：说出&quot;入职第一天做什么&quot;&quot;">​</a></h3><blockquote><p>&quot;如果我通过了，我的第一周会是： <strong>第 1 天</strong>跟主管过一遍我（A/B/C）名单；<strong>第 2–3 天</strong>把前 20 个人的情况电话过一遍； <strong>第 4–5 天</strong>约出第 1 个面谈；<strong>周末</strong>跟引荐人跑一场活动。 一周之内我要有第一次真实面谈。&quot;</p></blockquote><hr><h2 id="q6" tabindex="-1">8. 第 6 题：了解保险工作模式吗？怎么开展业务？怎么开拓客户？ <a class="header-anchor" href="#q6" aria-label="Permalink to &quot;8. 第 6 题：了解保险工作模式吗？怎么开展业务？怎么开拓客户？ {#q6}&quot;">​</a></h2><h3 id="评分点-1" tabindex="-1">评分点 <a class="header-anchor" href="#评分点-1" aria-label="Permalink to &quot;评分点&quot;">​</a></h3><p>客户的开拓能力。<strong>这题考&quot;你能不能落地&quot;。</strong></p><h3 id="工作模式-要说主管的内部语言" tabindex="-1">工作模式（要说主管的内部语言） <a class="header-anchor" href="#工作模式-要说主管的内部语言" aria-label="Permalink to &quot;工作模式（要说主管的内部语言）&quot;">​</a></h3><p>说得出下面的日常，主管就知道你不是外行：</p><table tabindex="0"><thead><tr><th>维度</th><th>我的理解</th></tr></thead><tbody><tr><td><strong>时间</strong></td><td>自主管理，早起安排当天行程；晚间是活动/社交时段</td></tr><tr><td><strong>主线</strong></td><td>活动 + 转介绍 <strong>双轮</strong>：活动获取新面孔，转介绍出高意向</td></tr><tr><td><strong>日常动作</strong></td><td>邀约 → 面谈 → 方案 → 跟进 → 成交 → 转介绍，循环</td></tr><tr><td><strong>核心纪律</strong></td><td>日程不空；每天加好友；每周复盘；每场活动必做跟进</td></tr><tr><td><strong>心理常态</strong></td><td>被拒绝是日常，被当&quot;推销&quot;是日常</td></tr></tbody></table><blockquote><p>&quot;我理解这份工作的常态是<strong>被拒绝</strong>，产出靠的是<strong>稳定的动作量</strong>而不是灵感。 所以我的做法会是：把动作量变成日程表，靠系统出单，而不是靠某一单碰运气。&quot;</p></blockquote><h3 id="客户开拓-分四条渠道-每条给动作和数量" tabindex="-1">客户开拓：分四条渠道 + 每条给动作和数量 <a class="header-anchor" href="#客户开拓-分四条渠道-每条给动作和数量" aria-label="Permalink to &quot;客户开拓：分四条渠道 + 每条给动作和数量&quot;">​</a></h3><p>呼应你博客里的 <a href="./05-获客转介绍">获客与转介绍</a>：</p><table tabindex="0"><thead><tr><th>渠道</th><th>我的第一个月动作</th></tr></thead><tbody><tr><td><strong>缘故市场</strong></td><td>盘点（<strong>X</strong>）个熟人，按 A/B/C 分层；A 类这周就约</td></tr><tr><td><strong>活动获客</strong></td><td>每月参加（<strong>X</strong>）场；每场后 48 小时内跟进全场留资</td></tr><tr><td><strong>社群/线上</strong></td><td>每周发（<strong>X</strong>）条保险相关内容，不刷屏、不群发</td></tr><tr><td><strong>转介绍</strong></td><td>每成交/每服务完一个客户，就自然提一次转介绍（见 <a href="./04-促成成交">促成成交</a>）</td></tr></tbody></table><h3 id="🎯-关键-给出-第一周-的动作清单" tabindex="-1">🎯 关键：给出&quot;第一周&quot;的动作清单 <a class="header-anchor" href="#🎯-关键-给出-第一周-的动作清单" aria-label="Permalink to &quot;🎯 关键：给出&quot;第一周&quot;的动作清单&quot;">​</a></h3><p>主管判断新人靠不靠谱，就看你是不是有<strong>具体的下一步</strong>：</p><blockquote><p>&quot;我的第一个月这样排：</p><ul><li>每周新增好友（<strong>X</strong>）个</li><li>每月参加活动（<strong>X</strong>）场</li><li>每月完成面谈（<strong>X</strong>）次</li><li>每周日晚上做一次复盘：本周见了谁、卡在哪、下周做什么&quot;</li></ul></blockquote><hr><h2 id="q7" tabindex="-1">9. 第 7 题：个性化提问 —— 家人支持吗？孩子谁照顾？ <a class="header-anchor" href="#q7" aria-label="Permalink to &quot;9. 第 7 题：个性化提问 —— 家人支持吗？孩子谁照顾？ {#q7}&quot;">​</a></h2><h3 id="评分点-2" tabindex="-1">评分点 <a class="header-anchor" href="#评分点-2" aria-label="Permalink to &quot;评分点&quot;">​</a></h3><p>获得的支持、投入度。<strong>这是最容易翻车的一题，也是最少人准备的一题。</strong></p><h3 id="潜台词" tabindex="-1">潜台词 <a class="header-anchor" href="#潜台词" aria-label="Permalink to &quot;潜台词&quot;">​</a></h3><blockquote><p><strong>&quot;你会不会干两个月，因为家里事就跑了？&quot;</strong></p></blockquote><h3 id="🚨-上场前必做-和家里人对齐口径" tabindex="-1">🚨 上场前必做：和家里人对齐口径 <a class="header-anchor" href="#🚨-上场前必做-和家里人对齐口径" aria-label="Permalink to &quot;🚨 上场前必做：和家里人对齐口径&quot;">​</a></h3><p><strong>不要等主管问细节才暴露困难。</strong> 提前和家人明确 4 件事：</p><table tabindex="0"><thead><tr><th>#</th><th>要对齐的事</th><th>为什么</th></tr></thead><tbody><tr><td>1</td><td><strong>收入预期</strong>：前 3-6 个月可能不稳定，家里能不能接受</td><td>这是最容易吵架的点</td></tr></tbody></table><p>、</p><h3 id="答法-先给结论-再给安排-最后给保障" tabindex="-1">答法：先给结论，再给安排，最后给保障 <a class="header-anchor" href="#答法-先给结论-再给安排-最后给保障" aria-label="Permalink to &quot;答法：先给结论，再给安排，最后给保障&quot;">​</a></h3><blockquote><p>&quot;家里<strong>支持</strong>。（<strong>第一句必须是明确的支持，不能犹豫</strong>）</p><p>具体已经安排好了：</p><ul><li>时间上我清楚保险的作息是<strong>早起 + 晚间/周末活动</strong>，家里也知道这个节奏；</li><li><strong>三个月收入目标我和家里沟通过</strong>，他们知道前期会有一个爬坡期。 我这边<strong>没有牵绊</strong>，可以全投入。&quot;</li></ul></blockquote><hr><h2 id="_10-📌-面试前-1-天-checklist" tabindex="-1">10. 📌 面试前 1 天 checklist <a class="header-anchor" href="#_10-📌-面试前-1-天-checklist" aria-label="Permalink to &quot;10. 📌 面试前 1 天 checklist&quot;">​</a></h2><ul><li>[ ] <strong>自我介绍</strong> 掐表练 3 遍，卡在 <strong>1:50–2:10</strong></li><li>[ ] <strong>三个数字</strong> 确认：认识引荐人（<strong>X</strong>）个月 / 参加过（<strong>X</strong>）场活动 / 三个月目标（<strong>X</strong>）</li><li>[ ] <strong>A/B/C 客户名单</strong>列出（<strong>X</strong>）人，标好优先级</li><li>[ ] <strong>友邦功课</strong>：成立时间、内地进入年份、口号、2-3 条产品线、代理人制度特点</li><li>[ ] <strong>家庭口径</strong>和家人对过：收入预期 / 社保 / 时间 / 孩子谁带</li><li>[ ] <strong>挑战题</strong>选定 1 个，配套应对动作</li><li>[ ] <strong>优势</strong>只说 3 个，每个有证据</li><li>[ ] 反问准备 2-3 个</li></ul><hr><h2 id="_11-反问环节-别放过" tabindex="-1">11. 反问环节（别放过） <a class="header-anchor" href="#_11-反问环节-别放过" aria-label="Permalink to &quot;11. 反问环节（别放过）&quot;">​</a></h2><p>主管问完通常会问&quot;你有什么想问的&quot;。<strong>问得好 = 加分，问不到点 = 减分。</strong></p><h2 id="_13-一页速记-临场只看这个" tabindex="-1">13. 一页速记（临场只看这个） <a class="header-anchor" href="#_13-一页速记-临场只看这个" aria-label="Permalink to &quot;13. 一页速记（临场只看这个）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>题</th><th>核心动作</th><th>关键句</th></tr></thead><tbody><tr><td>1 自我介绍</td><td>行业下行 + AI 上行 → 副业动机 → 能力硬接</td><td>经历要<strong>接到风险/决策</strong>，不要背技术栈</td></tr><tr><td>2 引荐人</td><td>三个数字 + 观察</td><td>&quot;他们第一句问的是&#39;出事了怎么办&#39;&quot;</td></tr><tr><td>3 友邦了解</td><td>抄官方数字</td><td>把「健康长久好生活」翻译成业务理解</td></tr><tr><td>4 销售观/优势/挑战</td><td>3 个优势 + 1 个真挑战</td><td>挑战必须配应对动作</td></tr><tr><td>5 三个月目标</td><td>三档 + 逐月拆解</td><td>说&quot;我第一周就有第一次面谈&quot;</td></tr><tr><td>6 工作模式/拓客</td><td>双轮 + 四渠道 + 数量</td><td>&quot;每周 X 新增、每月 X 面谈&quot;</td></tr><tr><td>7 家庭支持</td><td>先说支持 + 再给安排</td><td>社保不断缴 + 目标已沟通</td></tr></tbody></table><blockquote><p><strong>三个致命词，烂熟于心：</strong><strong>数字</strong>（量化一切）· <strong>动作</strong>（落到可验证的下一步）· <strong>安排</strong>（家庭已谈妥）</p></blockquote><hr><h2 id="🔗-相关文章" tabindex="-1">🔗 相关文章 <a class="header-anchor" href="#🔗-相关文章" aria-label="Permalink to &quot;🔗 相关文章&quot;">​</a></h2><ul><li><a href="./01-酒会活动">一、酒会活动</a> —— 活动获客全流程</li><li><a href="./02-客户面谈">二、客户面谈</a> —— 需求分析</li><li><a href="./03-保障方案">三、保障方案</a> —— 方案设计</li><li><a href="./04-促成成交">四、促成成交</a> —— 促成与转介绍</li><li><a href="./05-获客转介绍">五、获客与转介绍</a> —— 客户分类管理</li></ul>',100)])])}const b=o(n,[["render",s]]);export{u as __pageData,b as default};
